(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["ca"] = {"ui":{"skip":"Salta al contingut","back":"← Torna a AI-gile","lang.button":"Idioma: {name}","lang.dialog":"Tria un idioma","lang.search":"Cerca idiomes","lang.none":"Cap idioma coincideix","lang.notYet":"{name} encara no està traduït","theme.aria":"Canvia entre el tema clar i el fosc","theme.toLight":"Canvia al tema clar","theme.toDark":"Canvia al tema fosc","words.underline":"Subratlla aquestes paraules a la pàgina","words.underlineHelp":"Passa per sobre o toca una paraula puntejada per veure què vol dir.","index.title":"AI-gile: el teu equip de desenvolupament d'IA, en un sol tauler","index.description":"AI-gile és un tauler kanban per a equips d'IA que programen. Treballen mentre dorms; tu reps un munt curt de coses per decidir, provar i acceptar.","hero.logoAlt":"Icona del tauler d'AI-gile","hero.h1.html":"El teu equip de desenvolupament d'IA, en un sol&nbsp;tauler.","hero.alpha":"🐣 Pre-alfa tancada","hero.alphaTitle":"Aviat i sense acabar: gràcies per provar-ho!","hero.lede":"Construeixen mentre dorms. Et despertes amb un munt curt: unes quantes preguntes, unes quantes coses per provar, un diamant lila o dos. Clic, acceptat, i de tornada al teu cafè.","dl.windows":"Aplicació per a Windows","dl.browser":"Executa-ho al navegador","dl.soon":"Aviat","dl.notify":"🔔 Avisa'm quan s'obri","dl.notifySmall":"Alfa o beta","hero.secondary":"Àgil, però l'equip no necessita mai el cafè de la reunió d'estar dret. (Les fan igualment.)","pitch.h2":"AI-gile en tantes paraules com vulguis","pitch.lede":"Tria una llargada, d'una paraula a 144. Cada llargada és una descripció pròpia, escrita per a aquesta mida. Arrossega el control lliscant o fes servir les fletxes.","pitch.rangeLabel":"Llargada en paraules","pitch.dice":"🎲 una altra versió","pitch.words.one":"{n} paraula","pitch.words.other":"{n} paraules","pitch.letters.one":"{n} lletra","pitch.letters.other":"{n} lletres","pitch.chars.one":"{n} caràcter","pitch.chars.other":"{n} caràcters","count.line.html.one":"{n} targeta al tauler ara mateix","count.line.html.other":"{n} targetes al tauler ara mateix","features.aria":"Què fa","f.pile.h":"Un sol munt per a tu","f.pile.html":"<b>Per a tu</b> reuneix tot el que t'espera, de tots els projectes: preguntes, coses per provar, tasques que només pot fer una persona. La teva cua diu què toca ara i quant triga.","f.sleep.h":"Equips que treballen mentre dorms","f.sleep.p":"Cada projecte té un lead i un equip d'agents d'IA. Comenta una targeta i l'equip es desperta, fa la feina i te la torna amb passos que pot seguir una persona cansada.","f.tester.h":"Primer ho revisa un provador d'IA","f.tester.p":"Abans que res arribi a tu, un provador segueix els passos en una còpia de l'aplicació i mostra què ha vist, amb una captura. Repassa les que han passat i accepta-les d'un clic.","f.proof.h":"Proves, no promeses","f.proof.p":"Cada lliurament mostra què ha canviat: els fitxers, les diferències, les captures. No cal obrir cada aplicació per saber si ja està.","f.chat.h":"Xateja amb els teus leads","f.chat.p":"Una barra a l'estil de Discord: una icona per projecte, diamants lila per al que et necessita. Escriu una idea a un lead; la converteix en targetes i un pla, amb un botó ✅ Go.","f.tidy.h":"Es manté ordenat","f.tidy.p":"Les targetes relacionades es fonen en una, els títols embolicats s'arreglen i un control de tokens manté el codi lleuger. Menys coses entre les quals canviar, menys en què pensar.","f.private.h":"Teu, al teu ordinador","f.private.li1":"El tauler funciona a la teva pròpia màquina i només et respon a tu.","f.private.li2":"Els missatges privats entre persones estan xifrats d'extrem a extrem.","f.private.li3":"Sense comptes, sense rastrejadors, sense galetes.","f.lang.h":"En el teu idioma","f.lang.p":"Més de 120 idiomes, del neerlandès, el gal·lès i el japonès fins al pirata, en Yoda i el klingon, amb un canvi ràpid cap a l'anglès per a les paraules de desenvolupador.","tl.aria":"Cronologia des de la primera conversa fins al full de ruta","tl.h2":"Del primer xat a què ve ara","tl.lede":"Dates i hores reals, a la teva zona horària. A partir d'avui és el pla, sense dates promeses.","tl.today":"Avui","tl.planned":"previst","tl.cards.one":"{n} targeta","tl.cards.other":"{n} targetes","join.h2":"Uneix-t'hi","join.lede":"AI-gile el construeixen una persona petita i un gran nombre d'agents pacients. De moment és privat, en una alfa tancada amb amistats. Vols provar-ho quan s'obri?","join.btn":"Demana'n informació","join.small":"T'escriurem un correu, res més","footer.tag":"AI-gile. Sense rastrejadors, sense galetes, sense cafè de reunió.","footer.licence":"Llicència d'empresa","footer.status":"Estat","footer.privacy":"Què guardem","form.sending":"S'està enviant…","form.failed":"No ha funcionat: torna-ho a provar més tard.","form.offline":"No s'ha pogut contactar amb AI-gile: torna-ho a provar més tard.","form.keep":"Només ho fem servir per respondre't i després ho esborrem. Sense rastrejadors, sense galetes.","form.keepLink":"Què guardem","interest.title":"AI-gile: avisa'm quan s'obri l'alfa","interest.description":"Deixa el teu correu per saber quan s'obre l'alfa tancada o la beta d'AI-gile.","interest.h1":"🔔 Avisa'm quan s'obri","interest.lede":"AI-gile és en pre-alfa tancada. Deixa el teu correu i t'escriurem una sola vegada, quan hi hagi lloc per a tu.","interest.email":"El teu correu","interest.which":"Quina prova?","interest.alpha":"Alfa tancada: aviat, bruta, molts canvis","interest.beta":"Beta: més estable, més endavant","interest.both":"Qualsevol, la que arribi primer","interest.submit":"Apunta'm a la llista","interest.thanks":"Gràcies! Ja ets a la llista.","licence.title":"AI-gile: llicència d'empresa","licence.description":"Fas servir AI-gile a la teva empresa? Demana una llicència d'empresa gratuïta.","licence.h1":"📜 Llicència d'empresa","licence.lede":"Fas servir AI-gile a la feina? Explica'ns qui ets i què fas. Si fa algun bé, la llicència és gratuïta.","licence.company":"Empresa","licence.website":"Lloc web","licence.what":"A què us dediqueu","licence.how":"Com ajuda el món","licence.email":"Correu","licence.submit":"Sol·licita-la","licence.thanks":"Gràcies! Et respondrem per correu.","status.title":"Estat d'AI-gile","status.h1":"Estat d'AI-gile","status.quiet":"Tot tranquil","status.intro":"Funciona AI-gile ara mateix? Aquesta pàgina comprova el web, la compartició de taulers, les trucades i la descàrrega cada 5 minuts.","status.up":"Funciona (ha respost en {ms} ms)","status.slow":"No ha respost a l'última comprovació, ho tornem a provar","status.down":"Caigut: no ha respost a les dues últimes comprovacions","status.svc.web":"Web","status.svc.web.offers":"Aquest web: què és AI-gile i el formulari d'interès","status.svc.boards":"Compartició de taulers","status.svc.boards.offers":"Taulers públics, missatges entre amics i invitacions","status.svc.calls":"Trucades","status.svc.calls.offers":"Veu, vídeo i compartició de pantalla a AI-gile","status.svc.download":"Descàrrega","status.svc.download.offers":"L'instal·lador per a Windows i els enllaços d'invitació","status.checking":"Comprovant…","status.offline":"Ara mateix no es pot contactar amb el servei d'estat (es torna a provar)","status.updated":"actualitzat {ago}","status.justNow":"ara mateix","status.min":"fa {n} min","status.hours":"fa {n} h","status.days":"fa {n} d","privacy.title":"AI-gile: què guardem","privacy.h1":"Què guardem","privacy.lede":"Versió curta: només el que ens envies, i no per gaire temps.","privacy.only":"Només el que ens envies: el que escrius en un formulari, com el teu correu. Res més sobre tu.","privacy.sealed":"Es segella perquè el nostre servidor no ho pugui llegir: al teu navegador abans que surti (en un navegador més antic, en el moment que arriba). Només el nostre propi tauler ho pot obrir.","privacy.server":"S'esborra del servidor tan bon punt arriba al nostre tauler. Tot el que encara hi sigui al cap de 30 dies s'esborra igualment.","privacy.board":"Ho guardem al nostre tauler només fins que t'hem respost, i després també ho esborrem d'allà.","privacy.none":"Sense rastrejadors, sense galetes, sense analítiques.","privacy.local":"El teu idioma i la tria de tema clar o fosc es queden al teu propi navegador. No se'ns envien mai.","privacy.ask":"Vols que s'esborri abans? Respon al nostre correu i digues-nos-ho.","live.h2":"Mira com es construeix, en directe","live.caption":"Cada targeta està amagada: veus la forma de la feina, no les paraules.","live.watching.one":"en directe: {n} mirant","live.watching.other":"en directe: {n} mirant","live.last.now":"L'última targeta s'ha mogut ara mateix","live.last.min.one":"L'última targeta s'ha mogut fa {n} min","live.last.min.other":"L'última targeta s'ha mogut fa {n} min","live.last.hour.one":"L'última targeta s'ha mogut fa {n} hora","live.last.hour.other":"L'última targeta s'ha mogut fa {n} hores","live.last.day.one":"L'última targeta s'ha mogut fa {n} dia","live.last.day.other":"L'última targeta s'ha mogut fa {n} dies","live.offline":"El tauler en directe es pren un respir. Torna d'aquí a poc.","live.cols":"Backlog|Per fer|En curs|L'equip ho revisa|Et toca provar|Per a l'equip|Fet"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robots.","Delegat."]},{"n":2,"texts":["Kanban robòtic.","Agents, ordenats.","Idees, fetes."]},{"n":3,"texts":["Kanban per a robots.","Idees que esdevenen funcions.","Kanban d'agents gratuït."]},{"n":5,"texts":["Un tauler kanban portat per agents.","Tu escrius targetes. Ells construeixen.","Gratuït, local, provat, una mica tonto."]},{"n":8,"texts":["Un tauler kanban gratuït on treballen agents d'IA.","Escriu una idea. Els agents la fan. Tu l'acceptes.","Àgil per a una persona i molts robots pacients."]},{"n":13,"texts":["Un tauler kanban al teu ordinador on els agents d'IA agafen les targetes.","Escriu una idea. Un equip d'agents la construeix. Un provador la revisa.","Gratuït, sense comptes, sense rastrejadors: un tauler, uns quants robots i tu al comandament."]},{"n":21,"texts":["AI-gile és un tauler kanban per treballar amb agents d'IA que programen. Ells agafen les targetes; tu les proves i les acceptes.","Cada projecte té un lead i un equip d'agents d'IA. Comenta qualsevol targeta i l'equip es posa a treballar de seguida.","Un tauler de tasques personal i gratuït que funciona al teu propi ordinador. Els treballadors són robots. Qui diu que sí ets tu."]},{"n":34,"texts":["Poses les idees en un tauler. Un equip d'agents d'IA les converteix en funcions que van, les prova i te les torna amb passos per provar-les. Res compta com a fet fins que ho dius tu.","AI-gile és un tauler kanban fet a casa que en Rich ha construït amb molta ajuda dels agents que ara gestiona. És gratuït, funciona al teu ordinador i es comparteix amb amistats, no es ven.","Imagina un tauler kanban normal, amb columnes des de Backlog fins a Fet, però amb targetes que agafen agents d'IA. Expliquen els avenços, pregunten quan s'encallen i sempre esperen el teu vistiplau."]},{"n":55,"texts":["AI-gile és un tauler kanban on l'equip és fet d'agents d'IA. Cada projecte té un lead que planifica la feina i ajudants que la construeixen. Quan una funció està a punt, un provador d'IA la prova i fa una captura, i després arriba al teu munt. Accepta-la, o comenta i la tornaran a fer.","Va començar com la manera que tenia una persona de seguir moltes sessions de programació amb IA alhora, i ha crescut fins a ser un tauler de debò. Funciona a la teva màquina, no demana compte i no té rastrejadors. És gratuït per a amistats i curiosos. També està sense acabar, així que compta amb arestes i alguna sorpresa.","Aquesta és la versió honesta. Les idees les has de tenir tu, i els resultats els has de revisar tu. El que fa AI-gile és tot el d'enmig: manté les targetes ordenades, desperta l'agent adequat quan comentes, mostra exactament què ha canviat i ho recull tot en un munt curt per a tu."]},{"n":89,"texts":["AI-gile és un tauler kanban gratuït que fas funcionar al teu propi ordinador. En lloc de persones, cada projecte té un equip d'agents d'IA: un lead que converteix les teves idees en targetes i un pla, i ajudants que agafen les targetes per ordre de prioritat. Quan alguna cosa està feta, un provador d'IA segueix els passos de prova i et mostra què ha vist. Després espera en un sol munt anomenat Per a tu. L'acceptes, o comentes i l'equip ho torna a intentar. Res no arriba mai a Fet sense tu.","Algunes coses que potser no esperes. Una guàrdia de nit manté plena la columna Per fer mentre dorms, triant targetes que no necessiten cap resposta teva. Un comptador de tokens mostra quant han gastat els agents avui i aquesta setmana, i el No Token Mode els diu que deixin de gastar. Pots escriure a amistats, i els missatges privats estan xifrats d'extrem a extrem. El tauler parla uns 120 idiomes, entre ells el neerlandès, el flamenc, el pirata i el klingon. Res d'això costa ni un cèntim, i ningú no intenta vendre't res.","AI-gile és un projecte petit i personal, no una empresa. En Rich volia cuidar diversos projectes de programació amb IA sense obrir cada aplicació per mirar-los, així que ell i els agents hi van construir un tauler, i després el van fer servir per construir la resta d'ells mateixos. És en pre-alfa tancada, cosa que vol dir que funciona, més o menys, per a un grapat d'amistats. No hi ha pàgina de preus, ni butlletí, ni pla de creixement. Si et sembla útil, pots demanar de provar-lo quan s'obri una mica més."]},{"n":144,"texts":["AI-gile és un tauler kanban per a una persona i molts agents d'IA. Funciona al teu propi ordinador i és totalment gratuït. Afegeixes projectes, i cada projecte té un lead i un equip petit. Xategues amb el lead, una mica com a Discord, i descrius una idea; el lead la converteix en targetes i un pla, i espera que premis Go. L'equip va fent les targetes per ordre de prioritat, amb una línia d'ordres senzilla pensada per a models de llenguatge. Abans que res et torni, un provador d'IA segueix els passos en una còpia de l'aplicació i hi adjunta una captura. La feina acabada arriba al teu munt amb els fitxers canviats i les diferències. L'acceptes, o deixes un comentari i l'equip es desperta i ho torna a intentar. Només tu pots moure una targeta a Fet. No hi ha comptes, ni rastrejadors, ni galetes, i tot es queda al teu ordinador.","Un dia amb AI-gile, més o menys. Al vespre deixes uns quants comentaris: aquest botó és al lloc equivocat, aquella llista hauria d'estar ordenada, podríem tenir un mode fosc. Te'n vas a dormir. Els agents llegeixen els comentaris, fan els canvis, els proven i te'ls tornen. Si a Per fer s'acaben les targetes, la guàrdia de nit l'omple des del backlog amb targetes que no necessiten cap resposta teva. Al matí hi ha un sol munt curt: un parell de preguntes i unes quantes coses per provar, cadascuna amb passos que pot seguir una persona endormiscada i una captura que mostra que funciona. Ho vas repassant, acceptes les bones i tornes la resta. Un comptador de tokens mostra el que ha gastat tot plegat, i el No Token Mode és per a les setmanes magres. Després esmorzes, cosa amb què els agents encara no poden ajudar.","Primer, què no és AI-gile. No és una startup, no es ven i ningú no recull les teves dades. És un tauler gratuït que funciona al teu ordinador, sense comptes, sense rastrejadors i sense galetes. El que sí és: un lloc ordenat per veure tots els projectes de programació amb IA alhora, amb un equip d'agents que fa les targetes i tu prenent les decisions. Fon les targetes relacionades, arregla els títols embolicats i vigila que el codi es mantingui lleuger. Parla uns 120 idiomes, del neerlandès i el flamenc fins al pirata i el klingon. Les amistats poden escriure's, en privat i xifrat. El van construir en Rich i un gran nombre d'agents pacients, sobretot fent-lo servir a ell mateix. És en pre-alfa tancada, així que en alguns llocs és bast. Si et sembla divertit, demana-ho amb educació i potser entraràs aviat."]}],"quips":{"1":"Una paraula. Agosarada. Potser massa.","3":"Tres paraules. Ja és més honest que la majoria de pàgines de producte.","8":"Vuit paraules. Encara més curt que una reunió d'estar dret.","21":"Per cert, les llargades són punts d'història. És clar que sí.","55":"Cinquanta-cinc paraules. S'han acabat dues targetes mentre ho llegies.","144":"Aquesta és la llarga. No n'hi ha cap de 233. Els agents se n'han anat a dormir."}},"timeline":{"first-idea.name":"La primera idea","first-idea.line":"La primera conversa, abans que existís cap línia de codi.","first-board.name":"Primer tauler","first-board.line":"Un tauler que segueix la seva pròpia construcció: targetes, columnes, arrossegar i deixar anar, projectes.","team-roles.name":"Equip i rols","team-roles.line":"Perfils d'agents, plantilles d'equip, espais i qui fa què.","install.name":"Instal·lació i versions","install.line":"Un zip que una amistat pot instal·lar, actualitzacions automàtiques, canals i tornar enrere.","usage-saver.name":"Estalvi d'ús","usage-saver.line":"Mesura què costen les execucions, mantén el codi lleuger, estalvia el teu límit.","friends.name":"Amistats i compartir","friends.line":"Missatges privats, un relé xifrat, invitacions, rols i projectes compartits.","languages.name":"Idiomes","languages.line":"Cada text de pantalla en un fitxer d'idioma, amb el neerlandès i el flamenc primer.","ai-tester.name":"Provador d'IA","ai-tester.line":"Un provador revisa primer cada lliurament i mostra què ha vist.","website.name":"El web","website.line":"aigile.lol, l'avançament i aquesta cronologia.","streaming.name":"Xat i streaming","streaming.line":"Discord, Twitch, OBS, mode streamer, GIF i emojis.","no-ai.name":"Edició sense IA","no-ai.line":"Un tauler per a qui programa sense IA, i taulers públics.","night-watch.name":"Guàrdia de nit","night-watch.line":"Un vigilant i un Scrum Master mantenen els equips en feina mentre dorms.","p-more.name":"Tota la resta","p-more.line":"Idees més petites que encara esperen el seu torn.","p-android.name":"Mòbil i Android","p-android.line":"Arriba al teu tauler des del mòbil, i després una aplicació nativa d'Android.","p-release.name":"Alfa i més enllà","p-release.line":"Alfa tancada, el web en directe, i després la beta.","p-languages.name":"Més idiomes","p-languages.line":"Més de cent idiomes, i un mode d'immersió per a qui n'aprèn.","p-engines.name":"Més motors d'IA","p-engines.line":"Tria Claude, Codex o Gemini per a cada agent.","p-pro.name":"Pràctica professional","p-pro.line":"Etiquetes de risc, portes de fusió, targetes d'incidències i proteccions.","p-self.name":"Tenir cura de tu","p-self.line":"Mode cansat, recordatoris d'autocura i les 4:20.","p-servers.name":"Servidors i escala","p-servers.line":"Configuració global de servidors, rols i planificació per créixer.","p-livestream.name":"Extres de streaming","p-livestream.line":"Xat de Twitch, emojis propis i una vista pública en directe."},"words":{"button":"📖 Termes de programació","h":"📖 Words explained","intro":"The words you meet in AI-gile, in plain language: building it, changing it safely, keeping it running for the people who use it, and working as a team with AI.","search":"Cerca una paraula…","none":"Cap paraula coincideix.","close":"Tanca","count":{"one":"{count} word","other":"{count} words"},"groups":[{"id":"build","name":"🛠️ Building it"},{"id":"change","name":"🔀 Changing it safely"},{"id":"run","name":"🛎️ Running a service"},{"id":"team","name":"🤝 Working as a team (and with AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"La carpeta del projecte amb el codi i tot l'historial de commits, normalment també desada a GitHub.","also":["repositori"]},{"id":"branch","g":"build","word":"Branca","text":"Una línia de feina separada dins del codi, perquè es puguin fer canvis sense tocar la versió principal.","also":["branch","branches","branques"]},{"id":"commit","g":"build","word":"Commit","text":"Una instantània desada del codi, amb una nota breu del que ha canviat. Sempre pots tornar a una.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Enviar les instantànies desades (commits) d'aquest ordinador a GitHub, perquè tinguin còpia de seguretat i es comparteixin."},{"id":"merge","g":"build","word":"Merge","text":"Ajuntar els canvis d'una branca de nou a la versió principal."},{"id":"pr","g":"build","word":"Pull request","text":"Demanar que els canvis d'una branca es revisin i s'ajuntin a la versió principal.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactorització","text":"Endreçar el codi sense canviar el que fa: fitxers més petits, noms més clars, menys repeticions."},{"id":"bug","g":"build","word":"Bug","text":"Alguna cosa que no funciona com hauria.","also":["bugs","error"]},{"id":"test","g":"build","word":"Prova","text":"Provar una feina acabada per comprovar que fa el que es va demanar, abans d'acceptar-la.","also":["proves","provar","provis","test","tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Short for quality assurance: the automatic checks that run before anything goes live. When QA is red, something failed, and it can’t go live until that is fixed.","also":["quality checks"]},{"id":"deploy","g":"change","word":"Deploy","text":"Posar una versió nova en producció, per exemple en un servidor on la gent la fa servir."},{"id":"release","g":"change","word":"Release","text":"A named bundle of finished work that goes live together, with short notes on what changed. 🚀 Releases writes the notes from the done cards.","also":["releases"]},{"id":"rollback","g":"change","word":"Roll back","text":"Going back to the last version that worked when a new one causes trouble. In AI-gile it makes a checklist of the undo steps written on each change.","also":["rollback","roll-back","rolled back"]},{"id":"live","g":"change","word":"Live","text":"The real version that people use, as opposed to a copy for trying things out. Developers also call it production.","also":["production"],"noTip":1},{"id":"change","g":"change","word":"Change","text":"A planned change to something people rely on, written down first: what, why, the risk, when, and how to undo it. Start one with 🔀 Raise a change.","also":["change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Something that could go wrong, scored on how likely and how bad it would be. ⚠️ Risks keeps them in one list, highest score first, each with a date to look again.","also":["risks","risk register"]},{"id":"chgwin","g":"change","word":"Change window","text":"The times when changes may go live, such as a quiet Tuesday evening. Outside a window a change card can’t be finished, unless it is an emergency.","also":["change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"A quick vote just before a change goes live: each person who has to approve says Go or No go. It only goes ahead when they agree.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Approval","text":"Waiting for a yes before work starts. A card a friend raises, or a change, waits in ✅ Approvals until you approve or decline it.","also":["approvals"]},{"id":"quiettime","g":"change","word":"Quiet time","text":"A stretch of time, like a stream, a demo or the night, when nothing goes live. The teams keep working and testing, but going live waits until it ends. Elsewhere it is called a change freeze.","also":["quiet times","change freeze"]},{"id":"service","g":"run","word":"Service","text":"Something you built that people rely on, like a website or an app, looked after so it keeps working. Tick “This project is a service” and say what it offers, who uses it and who is on call.","also":["services"]},{"id":"uptime","g":"run","word":"Uptime check","text":"An automatic check, every few minutes, that your service still answers. If it fails several times in a row, AI-gile opens an incident card by itself.","also":["uptime","uptime checks"]},{"id":"statuspage","g":"run","word":"Status page","text":"A public page that shows whether a service is working (green, orange or red) with the latest update, so the people who use it can check instead of asking.","also":["status pages"]},{"id":"incident","g":"run","word":"Incident","text":"Something that is broken for the people using it right now, like the website being down. A 🔥 incident card jumps the queue: getting it working again comes first.","also":["incidents"]},{"id":"major","g":"run","word":"Major incident","text":"A big incident: many people affected, or money or data at risk. One button puts every team on it (swarm), wakes whoever is on call and asks for a status update every 30 minutes.","also":["major incidents"]},{"id":"oncall","g":"run","word":"On call","text":"Being the one who answers when something breaks, even at night. Each service has an on-call team member who is woken first for its incidents.","also":["on-call"]},{"id":"replyby","g":"run","word":"Reply-by time","text":"How long a card may wait for a first answer, for example an hour for an incident. After that it gets a red clock, so nothing is quietly forgotten. Also called a response target.","also":["reply-by times","response target","response targets"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"A short look back after an incident: what happened, what helped and what to change, without blaming anyone. An incident can’t be closed without one.","also":["post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Problem","text":"The hidden cause behind one or more incidents. A 🧩 problem card groups incidents that keep coming back, so the cause is found and fixed for good.","also":["problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Root cause","text":"The real reason something broke, not just what you saw going wrong. Fix the root cause and the incident stops coming back.","also":["root causes"]},{"id":"workaround","g":"run","word":"Workaround","text":"A way to keep things working until the real fix is ready, like restarting something when it gets stuck. It is written on the problem card so nobody has to work it out again.","also":["workarounds"]},{"id":"knownerror","g":"run","word":"Known error","text":"A problem whose cause is understood and that has a workaround, but isn’t fixed yet. 🧩 Known errors lists them, so everyone uses the workaround instead of digging again.","also":["known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Step-by-step instructions for fixing a known kind of trouble, so it is done the same way, quickly, every time. After a big incident the team can propose one for you to OK.","also":["runbooks"]},{"id":"backup","g":"run","word":"Backup","text":"A saved copy of your data from earlier, to fall back on if something is lost or damaged. AI-gile makes a backup of your boards every day.","also":["backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Restore","text":"Putting data back from a backup. A backup only really counts once you know it can be restored, so it is worth trying now and then.","also":["restored"]},{"id":"backlog","g":"team","word":"Backlog","text":"Idees i feina que encara no estan planificades. No es treballa en res d'allà fins que passa a Per fer."},{"id":"sprint","g":"team","word":"Sprint","text":"Un període curt de feina (sovint una o dues setmanes) amb un conjunt acordat de targetes per acabar.","also":["sprints"]},{"id":"standup","g":"team","word":"Stand-up","text":"Una revisió ràpida: què ha fet cada membre de l'equip, què farà després i què l'atura.","also":["standup","stand-ups"]},{"id":"kanban","g":"team","word":"Kanban","text":"Un tauler amb columnes (Per fer, En curs, Fet) on les targetes es mouen d'esquerra a dreta a mesura que avança la feina."},{"id":"wip","g":"team","word":"Límit de WIP","text":"Work in progress: el màxim de targetes que hauria de tenir una columna, perquè l'equip acabi les coses abans de començar-ne més.","also":["WIP"]},{"id":"dod","g":"team","word":"Definition of Done","text":"The team’s short checklist of what “finished” means, like tested and explained, before a card is handed to you. Its twin, the Definition of Ready, says when a card is clear enough to start.","also":["Definition of Ready"]},{"id":"testpile","g":"team","word":"Test pile","text":"The finished cards waiting for you to try, one after another. Accept one or send it back with a note, and the next one comes up.","also":["test piles"]},{"id":"retro","g":"team","word":"Retro","text":"A look back at how the team works, to agree on one thing to do better. In AI-gile a retro suggests a change to the team’s ways of working, and you say Go or Not yet.","also":["retros","retrospective","retrospectives"]},{"id":"peerreview","g":"team","word":"Peer review","text":"A second pair of eyes: another AI checks each card’s work before it reaches you, so fewer mistakes get through.","also":["code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"All hands on deck: every team drops other work to help on one urgent project until it is sorted. Other projects wait meanwhile.","also":["swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"The one who keeps the work flowing: spots stuck cards, nudges the teams and reminds you of what is waiting. In AI-gile the Lead Scrum Master does this across every project.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agent","text":"Una IA que treballa pel seu compte en una tasca: llegeix el codi, fa canvis, executa comprovacions i informa del resultat.","also":["agents"]},{"id":"token","g":"team","word":"Token","text":"La unitat amb què es compta l'ús de la IA: més o menys unes quantes lletres de text llegides o escrites. Menys tokens, més pla restant.","also":["tokens"]},{"id":"hook","g":"team","word":"Hook","text":"Una ordre petita que s'executa sola en un moment determinat, p. ex. quan s'inicia una sessió d'IA, perquè l'equip senti els teus comentaris.","also":["hooks"]}]}};
